#!/bin/bash
# land-planner-eats-again.sh — the weekly meal planner fix: legacy cuisine
# labels ('north-indian' et al) fold into the corpus vocabulary, and the
# composer's last-resort net now relaxes the authoritative mix, so a stranded
# slot is impossible again.
#
# BACKEND ONLY (together-city-chat). Push, and Railway rebuilds — no
# migration. Existing profiles start working without being re-saved.
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-chat ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

LOG="$(git log --oneline -40)"
MARK="The header reads left to right"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\" — run land-header-reads.sh first."; exit 1 ;;
esac
NEEDS="A label the engine never heard of must not cost anybody their dinner"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

PATCH="$(mktemp "${TMPDIR:-/tmp}/meal.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="848ffd7d2e9ef79ed716c2bace73c90649115ebdcd55df0c441b11a27714176e"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified"
git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
git am --keep-cr -C1 < "$PATCH"
echo "== committed"

cd together-city-chat
npx tsc --noEmit -p tsconfig.build.json
npx jest src/nutrition/legacy-cuisine-label.spec.ts src/nutrition/one-cuisine-one-card.spec.ts src/nutrition/cuisine-pref.spec.ts src/nutrition/cuisine-vocabulary.spec.ts
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS"
echo " Backend only — push and Railway rebuilds. Legacy profiles get"
echo " real dinners without being re-saved."
echo "==============================================================="
